package com.yuegang.zhihui.training.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.training.api.*;import java.math.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class TrainingProgressService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public TrainingProgressService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public ProgressView heartbeat(long user,LearningHeartbeat h){return tx.execute(s->{long assignment=id(h.assignmentId()),chapter=id(h.chapterId());Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM training_assignment WHERE id=? AND user_id=? AND status IN ('ASSIGNED','IN_PROGRESS')",Integer.class,assignment,user);if(owned!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("INSERT INTO training_chapter_progress(assignment_id,chapter_id,last_nonce) VALUES(?,?,?) ON DUPLICATE KEY UPDATE assignment_id=VALUES(assignment_id)",assignment,chapter,h.nonce());int changed=jdbc.update("UPDATE training_chapter_progress p JOIN training_chapter c ON c.id=p.chapter_id SET p.active_seconds=p.active_seconds+?,p.last_nonce=?,p.completed=(p.active_seconds+?>=c.minimum_active_seconds),p.completed_at=CASE WHEN p.active_seconds+?>=c.minimum_active_seconds THEN COALESCE(p.completed_at,NOW(6)) ELSE NULL END,p.version=p.version+1 WHERE p.assignment_id=? AND p.chapter_id=? AND (p.last_nonce IS NULL OR p.last_nonce<>?)",h.activeSeconds(),h.nonce(),h.activeSeconds(),h.activeSeconds(),assignment,chapter,h.nonce());jdbc.update("UPDATE training_assignment SET status='IN_PROGRESS',version=version+1 WHERE id=? AND status='ASSIGNED'",assignment);completeIfEligible(assignment);return view(user,assignment);});}public ProgressView get(long user,String assignment){return view(user,id(assignment));}private void completeIfEligible(long assignment){jdbc.update("UPDATE training_assignment a SET status='COMPLETED',completed_at=NOW(6),version=version+1 WHERE a.id=? AND a.status<>'COMPLETED' AND NOT EXISTS(SELECT 1 FROM training_chapter c LEFT JOIN training_chapter_progress p ON p.chapter_id=c.id AND p.assignment_id=a.id WHERE c.course_id=a.course_id AND COALESCE(p.completed,FALSE)=FALSE)",assignment);}private ProgressView view(long user,long assignment){return jdbc.query("SELECT a.id,a.course_id,a.user_id,a.status,a.version,(SELECT COUNT(*) FROM training_chapter WHERE course_id=a.course_id) total,(SELECT COUNT(*) FROM training_chapter_progress WHERE assignment_id=a.id AND completed=TRUE) done,(SELECT MAX(score) FROM training_quiz_attempt WHERE assignment_id=a.id) best,(SELECT MIN(c.id) FROM training_chapter c LEFT JOIN training_chapter_progress p ON p.chapter_id=c.id AND p.assignment_id=a.id WHERE c.course_id=a.course_id AND COALESCE(p.completed,FALSE)=FALSE) current FROM training_assignment a WHERE a.id=? AND a.user_id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);int total=r.getInt("total"),done=r.getInt("done");BigDecimal percent=total==0?BigDecimal.ZERO:BigDecimal.valueOf(done).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(total),2,RoundingMode.HALF_UP);Object current=r.getObject("current");return new ProgressView(Long.toString(r.getLong("id")),Long.toString(r.getLong("course_id")),Long.toString(r.getLong("user_id")),percent,r.getString("status"),current==null?null:current.toString(),(Integer)r.getObject("best"),r.getLong("version"));},assignment,user);}private static long id(String s){try{long v=Long.parseLong(s);if(v<=0)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
